window.careloopEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const esc=window.careloopEscape,$=s=>document.querySelector(s),P=window.CareloopPrograms;
