function currentProgram(){return programs.find(p=>p.id===programId)||null}
function blankDraft(p=currentProgram()){if(!p)return null;return {medication:p.medicationOptions[0]||'',status:'',dose:'',lastDose:'',missed:p.medicationOptions.length?'':'Not applicable',changes:'',symptoms:Object.fromEntries(p.symptoms.map(x=>[x,''])),urgent:[],impact:'',hydration:'',details:'',contact:'',notes:'',confirmed:false}}
let draft=blankDraft();
function persist(){if(programId&&draft)drafts[programId]=draft;}
function dataURL(path){return path+(path.includes('?')?'&':'?')+'mode='+workspaceMode+(workspaceMode==='demo'?'&view='+role+'&client='+encodeURIComponent(demoClientId):'')}
async function requestJSON(path,method='GET',body){
 const response=await fetch(path,{method,credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});
 let data;try{data=await response.json()}catch{throw Error('The service returned an unreadable response. Refresh and try again.')}
 if(!response.ok){const error=Error(data.message||data.error||'The request could not be saved.');error.data=data;error.status=response.status;throw error}return data;
}
function applyWorkspace(data){
 if(!Array.isArray(data.programs)||!Array.isArray(data.reports)||!data.workspace)throw Error('The workspace response is incomplete.');
 cloudWorkspace=data.workspace;funding=data.funding||null;profile=data.profile||null;demoClients=data.demoClients||[];availablePrograms=data.availablePrograms||[];window.careloopSetRewardOwner?.(workspaceMode==='account'?auth.user.id:'demo:'+cloudWorkspace.id+(role!=='patient'?':'+role:demoClientId==='alex'?'':':'+demoClientId));programs=data.programs.map(p=>({...P.normalizeProgram(p),invitationCode:p.invitationCode||null}));reports=data.reports;enrollments=data.enrollments||[];
 if(workspaceMode==='account')role=auth.user?.role||data.workspace.role;
 if(!programs.some(p=>p.id===programId)){programId=programs[0]?.id||null;selected=null;step=0;}
 draft=programId?(drafts[programId]||blankDraft()):null;
 if(workspaceMode==='demo'&&role==='patient'&&!window.careloopCommitment&&!enrollments.some(e=>e.commitment))publicCommitment();
}
async function loadWorkspace(){const revision=workspaceRevision;const data=await requestJSON(dataURL('/api/workspace'));if(revision!==workspaceRevision)return null;applyWorkspace(data);return data}
async function refreshDemoOrWorkspace(){if(workspaceMode==='demo')return restartDemo();return refreshWorkspace();}
async function refreshWorkspace(){if(workspaceLoading)return;const revision=workspaceRevision;workspaceLoading=true;workspaceError='';render();try{await loadWorkspace()}catch(e){if(revision===workspaceRevision)workspaceError=e.message}finally{if(revision===workspaceRevision){workspaceLoading=false;render()}}}
function updateReport(report){if(!report||typeof report.id!=='string')throw Error('The saved report was not returned.');const at=reports.findIndex(r=>r.id===report.id);if(at<0)reports.unshift(report);else reports[at]=report;return report}
function publicCommitment(){window.zkEnroll?.();const value=window.careloopCommitment;if(typeof value!=='string'&&typeof value!=='bigint')throw Error('The private enrollment is not ready. Open the reward workspace and try again.');return String(value)}
function dateLabel(){return new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}
function periodFor(p=currentProgram(),date=new Date()){
 const day=date.toISOString().slice(0,10);if(p.cadence==='Daily')return {id:day,label:day};
 if(p.cadence==='Monthly')return {id:day.slice(0,7),label:date.toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'})};
 const d=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()));d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));
 const year=d.getUTCFullYear(),week=Math.ceil((((d-new Date(Date.UTC(year,0,1)))/86400000)+1)/7);
 const n=p.cadence==='Fortnightly'?Math.ceil(week/2):week;return {id:year+'-'+(p.cadence==='Fortnightly'?'F':'W')+String(n).padStart(2,'0'),label:(p.cadence==='Fortnightly'?'Fortnight ':'Week ')+n+' · '+year};
}
function activeReports(){return reports.filter(r=>r.programId===programId)}
function alreadySubmitted(){return !!currentProgram()&&activeReports().some(r=>r.periodId===periodFor().id)}
function examples(){const p=currentProgram();if(!p)return [];return [{id:'EXAMPLE-'+p.id,programId:p.id,programConfig:p,isExample:true,participant:'P-EXAMPLE',period:'Example period',date:'Illustration',quality:'Complete',clinical:'Awaiting clinic review',payment:'Awaiting approval',answers:{...blankDraft(p),status:p.medicationOptions.length?'Taking as prescribed':'About the same',missed:'No',symptoms:Object.fromEntries(p.symptoms.map((x,i)=>[x,i===0?'Mild':'None'])),impact:'A little',hydration:'Yes',contact:'Yes',notes:'I would like to discuss the changes I noticed.'},audit:['Preloaded example — no submission, AI call or payment has occurred.'],decision:''}]}
function findReport(id){return reports.find(r=>r.id===id)||examples().find(r=>r.id===id)}
function badge(t){return '<span class="pill '+(/Pending|Awaiting|Priority|Symptoms flagged|Review requested|Clarification|failed|concern|On hold|blocked|limit reached|needs attention|Checking|confirming|funding|queued/i.test(t)?'warn':/Not |Demo|Example|training|untrained/i.test(t)?'neutral':'')+'">'+esc(t)+'</span>'}
function btn(t,a,cls=''){return '<button class="btn '+cls+'" onclick="'+esc(a)+'">'+t+'</button>'}
function notify(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function nav(p){stopPayoutWatch();if(page==='blockchain'&&p!=='blockchain')window.careloopBlockchain?.stop?.();page=p;selected=p==='blockchain'?(selected||activeReports()[0]?.id||null):null;persist();render();window.scrollTo(0,0);if(p==='blockchain'&&selected&&role==='patient')startPayoutWatch(selected);if(['checkin','demoReady','sponsor'].includes(p))void loadSponsorStatus();watchFunding()}
async function enterWorkspace(r,mode='demo'){
 if(workspaceLoading)return;if(window.careloopRewardBusy?.()){notify('Wait for the current wallet action to finish before changing workspaces.');return}if(mode==='demo'&&freshDemoOnEntry)mode='restart-demo';stopPayoutWatch();clearTimeout(fundingTimer);funding=null;fundingError='';const preferredProgram=mode==='restart-demo'?null:programId;if(mode==='restart-demo'){step=0;filter='All';editingProgramId=null;fundingForm={bucket:'rewards',amount:50};demoClientId='alex';sessionStorage.setItem('careloop-demo-client','alex');}const revision=++workspaceRevision;profile=null;demoClients=[];availablePrograms=[];aiBusy.clear();proofErrors.clear();sponsorStatus=null;reviewBusy.clear();workspaceLoading=true;workspaceError='';entered=true;programs=[];reports=[];enrollments=[];drafts={};draft=null;programId=null;selected=null;
 workspaceMode=auth.signedIn&&mode==='signed-in'?'account':'demo';entryMode=workspaceMode==='account'?'signed-in':'demo';role=workspaceMode==='account'?auth.user.role:['clinic','sponsor'].includes(r)?r:'patient';page=role==='sponsor'?'sponsor':role==='clinic'?'queue':'overview';render();
 try{if(workspaceMode==='demo'){await requestJSON(dataURL(mode==='restart-demo'?'/api/demo/restart':'/api/demo/start'),'POST',{});freshDemoOnEntry=false;}if(revision===workspaceRevision){await loadWorkspace();if(revision===workspaceRevision&&programs.some(p=>p.id===preferredProgram)){programId=preferredProgram;draft=blankDraft();}}}catch(e){if(revision===workspaceRevision)workspaceError=e.message}finally{if(revision===workspaceRevision){workspaceLoading=false;render();watchFunding();if(['clinic','sponsor'].includes(role))void loadSponsorStatus()}}
}
async function switchRole(r){if(workspaceMode==='account'){showLogin();return}await enterWorkspace(r,'demo');}
async function selectDemoClient(id){if(!demoClients.some(c=>c.id===id)||workspaceLoading)return;if(window.careloopRewardBusy?.()){notify('Wait for the current proof or wallet action to finish.');return}demoClientId=id;sessionStorage.setItem('careloop-demo-client',id);await enterWorkspace('patient','demo');}
