function login(){const clinic=loginRole==='clinic',register=authPanel==='register';return '<div class="login-shell"><section class="login-intro"><div class="logo"><span class="mark">↗</span>careloop.</div><div class="eyebrow">ONE WORKSPACE. MANY POSSIBILITIES.</div><h1>Better follow-up starts with a small check-in.</h1><p>Bring participants, clinics and study programs together. Thoughtful questionnaires. AI-assisted review. Transparent rewards.</p><div class="info">A flexible research demo, from medication follow-up to everyday wellbeing.</div><div class="footer">Human decisions. Participant privacy. Cardano Preprod.</div></section><section class="login-card"><div class="eyebrow">WELCOME TO CARELOOP</div><h2>'+(register?'Create your account':'Sign in to your workspace')+'</h2><div class="login-role"><button class="'+(!clinic?'active':'')+'" aria-pressed="'+!clinic+'" onclick="chooseLoginRole(\'patient\')"><strong>Participant</strong><small>My check-ins & rewards</small></button><button class="'+(clinic?'active':'')+'" aria-pressed="'+clinic+'" onclick="chooseLoginRole(\'clinic\')"><strong>Clinic</strong><small>Reports & program setup</small></button></div>'+(auth.signedIn?'<p>Signed in as <strong>'+esc(auth.user.displayName)+'</strong> · '+esc(auth.user.role==='clinic'?'Clinic':'Participant')+'</p>'+btn('Continue to my workspace',"enterWorkspace('"+auth.user.role+"','signed-in')")+' '+btn('Sign out','signOut()','secondary'):'<form onsubmit="event.preventDefault();authenticate()">'+(register?field('Display name','<input id="authName" type="text" autocomplete="name" maxlength="80" required>')+(!clinic?field('Preprod reward receiving address','<input id="authWallet" type="text" placeholder="addr_test1…" autocomplete="off" spellcheck="false" required>','Saved in your profile and used automatically for future rewards. Your wallet seed phrase is never needed.'):''):'')+field('Email address','<input id="authEmail" type="email" autocomplete="username" placeholder="you@example.com" maxlength="254" required>')+field('Password','<input id="authPassword" type="password" autocomplete="'+(register?'new-password':'current-password')+'" minlength="10" maxlength="128" placeholder="'+(register?'At least 10 characters':'Your password')+'" required>')+'<p id="authError" class="error" role="alert">'+esc(authError)+'</p><button class="btn" type="submit" '+(authPending?'disabled':'')+'>'+(authPending?'Please wait…':register?'Create '+(clinic?'clinic':'participant')+' account':'Sign in →')+'</button></form><p>'+btn(register?'Already have an account? Sign in':'New here? Create an account',"setAuthPanel('"+(register?'login':'register')+"')",'ghost')+'</p>')+'<div class="demo-divider"><span>Just exploring?</span></div>'+btn('Try '+(clinic?'clinic':'participant')+' demo',"enterWorkspace('"+loginRole+"','demo')",'secondary')+btn('Try sponsor demo',"enterWorkspace('sponsor','demo')",'secondary')+'<div class="info">Fictional information only. Programs and submitted fictional reports are saved online. Demo Refresh and Restart restore the starting credits and four clients. Account workspaces keep their saved history. Creating a clinic demo account does not verify a medical organization.</div></section></div>'}
function setAuthPanel(value){authPanel=value;authError='';render()}
async function authenticate(){if(authPending)return;if(window.careloopRewardBusy?.()){notify('Wait for the current wallet action to finish before signing in.');return}const email=$('#authEmail').value.trim(),password=$('#authPassword').value,displayName=$('#authName')?.value?.trim();authPending=true;authError='';const submit=document.querySelector('form button[type="submit"]');if(submit){submit.disabled=true;submit.textContent='Please wait…';}try{auth=await requestJSON('/api/auth/'+(authPanel==='register'?'register':'login'),'POST',{email,password,...(authPanel==='register'?{displayName,role:loginRole,recipientAddress:loginRole==='patient'?$('#authWallet')?.value?.trim():undefined}:{})});await enterWorkspace(auth.user.role,'signed-in');}catch(e){authError=e.message;$('#authError').textContent=authError;}finally{authPending=false;if(submit){submit.disabled=false;submit.textContent=authPanel==='register'?'Create account':'Sign in →';}}}
