function render(){if(!entered){$('#app').innerHTML=login();return}const p=currentProgram();
 const menus=role==='sponsor'?[['sponsor','◈','Sponsor funds'],['demoClients','◎','Demo clients'],['demoReady','✓','Demo readiness']]:role==='patient'?[['overview','◫','Overview'],['checkin','✎',(p?.cadence||'Program')+' check-in'],['reports','▤','My reports'],['rewards','◇','My rewards'],['program','◎','My programs'],['blockchain','⬡','Blockchain lab'],['demoReady','✓','Demo readiness']]:[['queue','▤','Review queue'],['program','◎','Programs'],['rewards','◇','Reward ledger'],['blockchain','⬡','Blockchain lab'],['demoReady','✓','Demo readiness']];
 $('#app').innerHTML='<div class="shell"><aside class="sidebar"><div class="logo"><span class="mark">↗</span>careloop<span style="color:#829568">.</span></div><div class="sublogo">BETTER FOLLOW-UP</div><nav class="nav" aria-label="Main navigation">'+menus.map(([p,i,t])=>'<button class="'+(page===p?'active':'')+'" onclick="nav(\''+p+'\')"><span>'+i+'</span>'+esc(t)+'</button>').join('')+'</nav><div class="sidebottom"><div class="info">Small check-ins.<br>A clearer picture over time.</div><div class="profile"><div class="avatar">'+(role==='patient'?'AL':role==='sponsor'?'SP':'CL')+'</div><div>'+esc(role==='patient'?(profile?.displayName||'Participant workspace'):role==='sponsor'?'Sponsor workspace':'Clinic workspace')+'<small>'+ (entryMode==='signed-in'?'Signed-in demo':'Fictional demo account')+'</small></div></div></div></aside><div><header class="topbar"><div class="program-picker"><label class="eyebrow" for="programSelect">ACTIVE DEMO PROGRAM</label><select id="programSelect" onchange="changeProgram(this.value)">'+programs.map(x=>'<option value="'+esc(x.id)+'" '+(x.id===programId?'selected':'')+'>'+esc(x.name)+'</option>').join('')+'</select></div><div class="user-actions">'+badge(role==='patient'?'Participant':role==='sponsor'?'Sponsor':'Clinic')+btn('Refresh','refreshDemoOrWorkspace()','secondary small-button')+(workspaceMode==='demo'?btn('Sponsor',"switchRole('sponsor')",'secondary small-button')+btn('Clinic',"switchRole('clinic')",'secondary small-button')+btn('Demo clients',"nav('demoClients')",'secondary small-button')+btn('Restart demo','restartDemo()','secondary small-button'):'')+btn('Account / demo','showLogin()','secondary small-button')+'</div></header><main class="content"><div class="notice">FICTIONAL DEMO · Programs, submitted reports and clinic reviews are saved online. Unsaved drafts stay in memory only. No doctor is notified.'+'</div>'+content()+'<div class="footer">Careloop · Thoughtful follow-up, human decisions.</div></main></div></div>';
}
function heading(ey,h,p,tag=''){return '<div class="heading"><div><div class="eyebrow">'+esc(ey)+'</div><h1>'+esc(h)+'</h1><p>'+esc(p)+'</p></div>'+(tag?badge(tag):'')+'</div>'}
function content(){
 const banner=(legacyRecords?'<p class="info">Older prototype records are still in this browser; new submissions are saved to your server workspace.</p>':'')+(workspaceLoading?'<div class="info" role="status">Loading the saved workspace…</div>':'')+(workspaceError?'<div class="card"><p class="error" role="alert">'+esc(workspaceError)+'</p>'+btn('Retry loading','refreshWorkspace()','secondary')+'</div>':'');
 if(page==='blockchain')return banner+(window.careloopBlockchain?window.careloopBlockchain.render({reports:activeReports(),program:currentProgram(),live:window.careloopChainSnapshot?.()}):heading('BLOCKCHAIN LAB','Blockchain lab is loading.','Refresh to try again.'));
 if(page==='sponsor'&&workspaceMode==='demo'&&role==='sponsor')return banner+sponsorFundingPage();
 if(page==='demoReady')return banner+demoReadiness();
 if(page==='demoClients'&&workspaceMode==='demo')return banner+demoClientPanel();
 if(page==='programEditor'&&role==='clinic')return banner+programEditor();
 if(!currentProgram())return banner+emptyWorkspace();
 let body;if(page==='checkin')body=checkin();else if(page==='reports')body=heading('YOUR CONTRIBUTION','Your saved reports','AI analysis, clinic review and payment are tracked separately.')+reportTable(activeReports(),false)+exampleSection();else if(page==='rewards')body=rewards();else if(page==='queue')body=selected?detail():queue();else if(page==='reportDetail')body=detail();else if(page==='program')body=program();else if(page==='done'){const r=findReport(selected);body=heading('CHECK-IN SAVED','Your report is saved online.','Follow this report’s real checks and Cardano payment below.')+(r?workflow(r)+livePayoutCard(r)+aiCard(r):'')+'<section class="card" style="margin-top:18px"><h2>Keep your private enrollment key</h2><p>Your report is saved online. Your private enrollment key stays on this device. Keep its recovery file to use this enrollment and claim rewards from another device.</p>'+btn('Download private recovery file','zkBackup()','secondary')+'<p class="muted">Keep this file private. Restore it in My rewards before submitting from a new device.</p></section><div class="actions">'+btn('View my reports',"nav('reports')")+(workspaceMode==='demo'?btn('Open clinic demo',"switchRole('clinic')",'secondary'):'')+'</div>';}else body=overview();return banner+body;
}
